.nav-tabs {
  &.tab-card{
    padding: 0 1.5rem;
    @media only screen and (max-width: $break-small) {
        padding: 0 1rem;
    }
    .nav-link{
        color: var(--color-500);
        background-color: transparent;
        border-bottom: 7px solid transparent;
        border-top: 0;
        border-left: 0;
        border-right: 0;
        margin-bottom: -4px;
        @media only screen and (max-width: $break-small) {
            padding-left: 14px;
            padding-right: 14px;
        }

        &.active,
        &:hover{
            border-color: var(--primary-color);
            color: var(--primary-color);
        }
    }
  }
  &.nav-tabs-new {
    border-bottom: 0;
    > li {
      > a {
        color: var(--color-600);
        margin: 0;
        margin-right: 5px;
        border: 1px solid var(--border-color);
        border-radius: 30px;
        padding: 7px 23px;
        background-color: transparent;

        &:hover,
        &:focus {
          background-color: var(--primary-color);
          color: $col-white;
        }
        &.active {
          color: $col-white;
          border: 1px solid var(--primary-color) !important;
          background: var(--primary-color);
        }
      }
    }
  }

  &.nav-tabs-new2 {
    border-bottom: 1px solid ar(--border-color);

    > li {
      > a {
        color: var(--color-600);
        padding: 7px 20px;
        margin-right: 5px;
        background-color: transparent;
        border: 0;
        font-size: 15px;

        &:hover,
        &:focus {
          color: var(--primary-color);
          border-bottom: 2px solid var(--primary-color) !important;
        }
        &.active {
          color: var(--primary-color);
          border-bottom: 2px solid var(--primary-color) !important;
          background-color: transparent;
        }
      }
    }
  }
}
