/* Layout */
#layout {
    &:before,
    &:after {
        position: fixed;
        height: 5px;
        width: 100%;
        content: "";
        z-index: 999;
        background-color: var(--primary-color);
    }
    &:before {
        top: 0;
    }
    &:after {
        bottom: 0;
    }

    @include media-breakpoint-down(lg) {
        &:before,
        &:after {
            height: 2px;
        }
    }

    // body layout version
    .body-layout-1{
        .menu-list{
            .m-link{
                color: var(--color-500);
                display: flex;
                align-items: center;
                padding: 6px;
                &:hover{
                    color: var(--primary-color);
                }
                i.fa{
                    width: 26px;
                }
            }
        }
        .order-1{
            background: var(--card-color);
            height: calc(100vh - 77px);
            min-width: 230px;
            max-width: 230px;
            padding: 14px 18px;
            margin-top: 2px;
            margin-left: 2px;
        }
        .order-2{
            height: calc(100vh - 77px);
            .list-group{
                li{
                    &:first-child{
                        border-radius: .75rem .75rem 0 0;
                    }
                    &:last-child{
                        border-radius: 0 0 .75rem .75rem;
                    }
                    &:hover{
                        .hover-actions{
                            display: block;
                        }    
                    }
                    .hover-actions{
                        position: absolute;
                        text-align: end;
                        display: none;
                        width: 165px;
                        right: 0;
                    }
                }
            }
        }
    
        @media only screen and (max-width: $break-medium) {
            .order-1{
                @include transition(ease .1s);
                position: fixed;
                box-shadow: 5px 1rem 1rem rgba($dark,.1);
                left: -400px;
                &.open{
                    left: 0;
                    z-index: 99;
                }
            }
            .order-1,
            .order-2{
                height: calc(100vh - 69px);
            }
        }
    }
}

#wrapper {
    &:before,
    &:after {
        position: fixed;
        height: 100vh;
        width: 5px;
        content: "";
        z-index: 999;
        top: 0;
        background-color: var(--primary-color);
    }
    &:before {
        left: 0;
    }
    &:after {
        right: 0;
    }
    @include media-breakpoint-down(md) {
        &:before,
        &:after {
        width: 2px;
        }
    }
}

#main-content {
    @include transition(all 0.3s ease-in-out);
    width: calc(100% - #{$sidebar-width});
    float: right;
    position: relative;
    margin-top: 61px;
    margin-bottom: 30px;
    padding: 0 40px;

    @include media-breakpoint-down(xl) {
        width: 100%;
        padding: 0;
    }
}

html.fullscreen-bg,
html.fullscreen-bg body,
html.fullscreen-bg #wrapper {
    height: 100%;
}

.h100vh {
    height: 100vh;
}
