/* cyrillic-ext */
@import url("https://fonts.googleapis.com/css?family=Ubuntu:300,400,500,700");

// Font Awesome
@import "../../../node_modules/font-awesome/scss/font-awesome.scss";

// summernote plugin font file
@font-face{
    font-family:"summernote";
    font-style:normal;
    font-weight:400;
    font-display:auto;
    src:url('../../fonts/summernote.eot');
    src:url('../../fonts/summernote.eot') format("embedded-opentype"),
    url('../../fonts/summernote.woff2') format("woff2"),
    url('../../fonts/summernote.woff') format("woff"),
    url('../../fonts/summernote.ttf') format("truetype")
}
// dropify plugin font file
@font-face {
    font-family: 'dropify';
    src: url("../../fonts/dropify.eot");
    src: url("../../fonts/dropify.eot#iefix") format("embedded-opentype"),
    url("../../fonts/dropify.woff") format("woff"),
    url("../../fonts/dropify.ttf") format("truetype"),
    url("../../fonts/dropify.svg#dropify") format("svg");
    font-weight: normal;
    font-style: normal; 
}
