  --white-color: #ffffff;
  --sidebar-color: #fcfcfc;
  --hc-font-color: #555555;
  --hc-bg-color: #f0f0f0;
}
[data-theme=high-contrast] .avatar.no-thumbnail {
  background-color: #212529;
}
