  --primary-color: #3B185F;
  --secondary-color: #FEC260;
  --primary-rgb: rgb(59, 24, 95);
  --chart-color1:	#3B185F;
  --chart-color2:	#FEC260;
  --chart-color3:	#ff80ad;
  --chart-color4:	#FF8474;
  --chart-color5:	#9F5F80;
  --primary-gradient: linear-gradient(145deg, var(--primary-color), var(--chart-color4));
