// bootstrap class overwrite css
.border,
.border-top,
.border-right,
.border-bottom,
.border-left,
.dropdown-divider {
  border-color: var(--border-color) !important;
}
.border-primary {
  border-color: var(--primary-color) !important;
}
.border-success {
  border-color: $color-success !important;
}
.border-danger {
  border-color: $color-danger !important;
}
.border-warning {
  border-color: $color-warning !important;
}
.border-info {
  border-color: $color-info !important;
}

.link-primary,
.link-primary a {
  color: var(--primary-color) !important;
}

// form-control
.form-control {
  border-color: var(--border-color);
  background-color: var(--card-color);
  color: var(--color-900);

  &::placeholder {
    color: var(--color-400);
  }
  &:focus {
    box-shadow: 0 0 10px rgba($dark, 0.15);
    background-color: var(--card-color);
    border-color: var(--primary-color);
    color: var(--primary-color);
  }

  &.form-control-lg {
    min-height: calc(1.5em + 1.8rem + 2px);
    &[type="file"] {
      line-height: 34px;
    }
  }
}
.form-select {
  border-color: var(--border-color);
  background-color: var(--card-color);
  color: var(--color-900);
  &::placeholder {
    color: var(--color-400);
  }
}
// form Switches css
.form-check-input {
  -webkit-appearance: none;
  &:checked {
    background-color: var(--primary-color);
    border-color: var(--primary-color);
  }
}
.input-group-text {
  border-color: var(--border-color);
  background-color: var(--border-color);
  color: var(--color-500);
}


.todo_list {
  .form-check-input {
    &:checked {
      + label {
        text-decoration: line-through;
      }
    }
  }
}

// Button
.btn {
  font-size: $font-size;

  &.btn-primary {
      background-color: var(--primary-color);
      border-color: var(--primary-color)
  }

  &.btn-light-primary {
      background-color: rgba(var(--primary-rgb), 0.15);
      color: var(--primary-color);
      border-color: transparent;

      &:hover{
          background-color: var(--primary-color);
          color: $white;
      }
  }
  &.btn-light-secondary{
      background-color: rgba($color-secondary, .15);
      color: $color-secondary;
      border-color: transparent;

      &:hover{
          background-color: $color-secondary;
          color: $white;
      }
  }
  &.btn-light-success{
      background-color: rgba($color-success, .15);
      color: $color-success;
      border-color: transparent;

      &:hover{
          background-color: $color-success;
          color: $white;
      }
  }
  &.btn-light-danger{
      background-color: rgba($color-danger, .15);
      color: $color-danger;
      border-color: transparent;

      &:hover{
          background-color: $color-danger;
          color: $white;
      }
  }
  &.btn-light-warning{
      background-color: rgba($color-warning, .15);
      color: $color-warning;
      border-color: transparent;

      &:hover{
          background-color: $color-warning;
          color: $white;
      }
  }
  &.btn-light-info{
      background-color: rgba($color-info, .15);
      color: $color-info;
      border-color: transparent;

      &:hover{
          background-color: $color-info;
          color: $white;
      }
  }

  &.btn-outline-primary {
      color: var(--primary-color);
      border-color: var(--primary-color);

      &:hover{
          background-color: var(--primary-color);
          color: $white;
      }
  }
  &.btn-outline-secondary {
      border-color: var(--border-color)
  }
  &.btn-outline-success{
      color: $color-success;
      border-color: $color-success;
      &:hover{
          background-color: $color-success;
          color: $white;
      }
  }
  &.btn-outline-danger{
      color: $color-danger;
      border-color: $color-danger;
      &:hover{
          background-color: $color-danger;
          color: $white;
      }
  }
  &.btn-outline-info{
      color: $color-info;
      border-color: $color-info;
      &:hover{
          background-color: $color-info;
          color: $white;
      }
  }

  &.btn-white {
      background-color: var(--color-fff);
      border-color: var(--color-fff);
      color: var(--color-700);
  }
  &.btn-dark {
      background-color: var(--color-900);
      border-color: var(--color-900);
      color: var(--color-400);
  }

  &.btn-lg {
      padding: .89rem 1rem;
      font-size: 1rem;
  }
}
.btn-group{
  .btn-check:checked+.btn-outline-primary,
  .btn-check:active+.btn-outline-primary,
  .btn-outline-primary:active,
  .btn-outline-primary.active,
  .btn-outline-primary.dropdown-toggle.show{
      background-color: var(--primary-color);
      border-color: var(--primary-color);
  }
}
button {
  &:focus {
  &:not(:focus-visible) {
    box-shadow: none;
  }
}
}
.accordion-button{
  background-color: var(--card-color);
  color: var(--color-600);
}

// dropdown menu
.dropdown-item{
  color: var(--color-700);
  &:hover,
  &:focus,
  &.active {
    background-color: var(--primary-color);
    color: $white;
  }
}

.dropdown-menu {
  border-color: var(--border-color);
  background: var(--card-color);
  color: var(--color-700);
  font-size: $font-size;
}
.after-none::after {
  display: none;
}

// navbar
.navbar-light {
  .navbar-nav {
    .nav-link {
      color: var(--color-500);
      &:hover,
      &:focus {
        color: var(--primary-color);
      }
    }
  }
}

// custom tab ui
.nav-tabs {
  border-color: var(--border-color);
  .nav-link.active,
  .nav-item.show .nav-link{
    color: var(--color-500);
    background-color: var(--card-color);
    border-color: var(--border-color) var(--border-color) var(--card-color);
  }
  &.menu-list{
    flex-direction: column;
    .nav-link{
        color: var(--color-500);
        display: flex;
        align-items: center;
        border-radius: .25rem;
        margin: 0;
        border: 0;
        padding: .6rem 0;

        &.active,
        &:hover{
            color: var(--primary-color);
            background-color: transparent;
            font-weight: bold;
        }

        i.fa{
            width: 26px;
        }
    }
  }
}

// nav pill
.nav-pills {
  .nav-link.active,
  .show > .nav-link {
    background-color: var(--primary-color);
  }
  .nav-link {
    color: var(--primary-color);
  }
}

// list-group design
.list-group-custom {
    .list-group-item {
        background-color: var(--card-color);
        border-color: var(--border-color);
        color: var(--color-500);
        
        &.hover,
        &.active {
            background-color: var(--primary-rgb);
            color: $white;
        }
    }
}

// progress bar design
.progress {
  background-color: var(--color-200);
}

// table
.table {
  border-color: var(--border-color);
  width: 100% !important;
  >:not(:first-child){
    border-color: var(--primary-color);
  }
  tr {
    th {
      border-color: var(--border-color);
      color: var(--color-800);
      text-transform: uppercase;
      font-size: 12px;
    }
    td {
      border-color: var(--border-color);
      color: var(--color-500);
      padding: 0.8rem 0.6rem;
    }
    &:hover {
      td {
        color: var(--color-900);
      }
    }
  }
  &.border-primary {
    tr {
      td {
        border-color: var(--primary-color);
      }
    }
  }
  &.table-dark {
    color: var(--color-fff) !important;
    tr {
      th,
      td {
        color: var(--color-fff) !important;
      }
    }
  }
  &.table-striped>tbody>tr:nth-of-type(odd)>*{
    color: var(--color-500);
    &:hover{
      color: var(--color-900);
    }
  }
}

// pagination
.page-item {
  &.disabled {
    .page-link {
      background-color: var(--border-color);
      border-color: var(--border-color);
    }
  }
  .page-link {
    background-color: var(--card-color);
    border-color: var(--border-color);
  }
}

// ProgressBar
.progress {
  &.vertical {
    width: 20px;
    height: 100%;
    float: left;
    margin-right: 20px;
  }
  &.wide {
    width: 60px;
  }
}

//
.modal-content{
  background-color: var(--card-color);
  .modal-header,
  .modal-footer{
    border-color: var(--border-color);
    color: var(--color-700);
  }
}

//
.accordion{
  .accordion-item{
    background-color: var(--card-color);
    border-color: var(--border-color);
  }
  .accordion-button{
    background-color: var(--border-color);
    color: var(--color-500);
    &:not(.collapsed){
      color: var(--primary-color);
      background-color: var(--border-color);
    }
  }  
}

// avatar
.avatar {
  width: 36px;
  min-width: 36px;
  height: 36px;

  &.xs{
      width: 16px;
      min-width: 16px;
      height: 16px;
      font-size: 8px;
  }
  &.sm{
      width: 26px;
      min-width: 26px;
      height: 26px;
  }
  &.lg{
      width: 56px;
      min-width: 56px;
      height: 56px;
  }
  &.xl{
      width: 90px;
      min-width: 90px;
      height: 90px;
  }
  &.xxl{
      width: 120px;
      min-width: 120px;
      height: 120px;
  }
  &.no-thumbnail{
      background-color: rgba(var(--primary-rgb), 0.15);
      color: var(--primary-color);
      font-weight: 600;
      display: flex;
      align-items: center;
      justify-content: center;
  }
}
// img upload 
.file-input{
  input{
      width: 0.1px;
      height: 0.1px;
      opacity: 0;
      overflow: hidden;
      position: absolute;
      z-index: -1;
  }
  label:hover{
      cursor: pointer;
      color: var(--primary-color);
  }
}
.image-input{
  position: relative;
  display: inline-block;
  background-repeat: no-repeat;
  background-size: cover;

  .avatar-wrapper{
      background-repeat: no-repeat;
      background-size: cover !important;
      width: 100%;
      height: 100%;
  }

  &.avatar{
      &.xxl{
          .file-input{
              position: absolute;
              bottom: 10px;
              right: 10px;
          }
      }
      &.xl{
          .file-input{
              position: absolute;
              bottom: 5px;
              right: 5px;
          }
      }
      &.lg{
          .file-input{
              position: absolute;
              bottom: -5px;
              right: -5px;
          }
      }
  }

  .file-input{
      label{
          background: var(--card-color);
          text-align: center;
          height: 24px;
          width: 24px;
          line-height: 24px;
          border-radius: 24px;
      }
  }
}
.datepicker>div {
  display: block;
}